const update = $input.first()?.json || {};
const msg = update.message || update.edited_message || {};
const chat = msg.chat || {};
const rawText = String(msg.text || '').trim();
const chatId = String(chat.id || '').trim();
let action = '';
let prompt = '';
let task_id = '';
let executor = 'dry_run';
if (/^\/run\b/i.test(rawText)) {
  action = 'run';
  prompt = rawText.replace(/^\/run\s*/i, '').trim() || 'Phase 3 smoke run';
} else if (/^\/codex\b/i.test(rawText)) {
  action = 'run';
  executor = 'codex';
  prompt = rawText.replace(/^\/codex\s*/i, '').trim() || 'Return TAC_CODEX_SMOKE_OK';
} else if (/^\/status\b/i.test(rawText)) {
  action = 'status';
  task_id = rawText.replace(/^\/status\s*/i, '').trim();
} else if (/^\/killall\b/i.test(rawText)) {
  action = 'killall';
} else if (rawText && !rawText.startsWith('/')) {
  action = 'run';
  executor = 'codex';
  prompt = [
    'FOLLOWUP_TASK: true',
    'Telegram follow-up message. First inspect the latest TAC task/result if needed and continue from the most recent related bounded workspace.',
    'If this is an approval, execute only the approved bounded scope and keep forbidden live mutations blocked unless explicitly approved.',
    '',
    'User message:',
    rawText,
  ].join('\n');
}
const supported = !!action && !!chatId;
const endpoint = action === 'killall' ? 'killall' : action === 'status' ? 'status' : 'run';
return [{ json: { supported, action, endpoint, runner_url: `http://172.17.0.1:8765/${endpoint}`, prompt, task_id, chat_id: chatId, executor, received_text: rawText } }];

const response = $json || {};
const result = response.result || {};
const status = String(result.status || (response.ok ? 'PASS' : 'UNKNOWN'));
const taskId = String(result.task_id || response.task_id || $node['Normalize Telegram Command'].json.task_id || 'unknown');
const summary = String(result.summary || response.message || response.error || 'No summary returned').slice(0, 3300);
const text = [
  '[TRUE AUTONOMOUS CONTROLLER]',
  `status: ${status}`,
  `task: ${taskId}`,
  '',
  summary,
  '',
  'commands:',
  `/status ${taskId}`,
  '/killall'
].join('\n').slice(0, 3900);
return [{ json: { status, task_id: taskId, telegram_text: text, chat_id: $node['Normalize Telegram Command'].json.chat_id } }];
